[[ ## document ## ]]
{
  "title": "CAM Reconciliation — Disputed Line Items Documentation",
  "path": "engagements/stonebridge-manufacturing/cam-reconciliation/disputed-line-items-documentation.docx",
  "document": {
    "blocks": [
      {
        "kind": "heading",
        "level": 1,
        "text": "CAM Reconciliation — Documentation of Disputed Line Items"
      },
      {
        "kind": "paragraph",
        "text": "Prepared by: Lucia Mendes, Senior Accountant, Tax\nDate: Friday delivery (as committed)\nEngagement: Stonebridge Manufacturing — FY2025 CAM Reconciliation"
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Disputed Line Item 1: Warehouse Lease CAM Charges — Property Tax Allocation"
      },
      {
        "kind": "paragraph",
        "text": "Stonebridge disputes the $12,480 property tax allocation included in the landlord's CAM statement for the warehouse at 4400 Industrial Parkway. Our review of the lease (Section 7.2) confirms CAM charges are limited to operating expenses directly attributable to the common areas; property taxes are a separate pass-through under Section 7.4 and should not be double-counted within the CAM pool. The landlord's reconciliation includes property taxes in both the CAM pool and as a separate line, resulting in a duplicate charge."
      },
      {
        "kind": "heading",
        "level": 3,
        "text": "Calculation"
      },
      {
        "kind": "table",
        "columns": ["Description", "Amount", "Basis"],
        "rows": [
          ["Property tax included in landlord's CAM pool (duplicate)", "$12,480.00", "Landlord's CAM schedule, line 14"],
          ["Property tax already passed through separately (Section 7.4)", "$12,480.00", "Lease exhibit C, schedule 2"],
          ["Duplicate amount to be removed from CAM charges", "$12,480.00", "Difference between the two inclusions"]
        ]
      },
      {
        "kind": "paragraph",
        "text": "Adjustment: Reduce CAM charges by $12,480.00. This is the exact dollar amount disputed and the calculation is the direct overlap of the two line items in the landlord's own schedules."
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Disputed Line Item 2: Common Area Utilities — Snow Removal Allocation"
      },
      {
        "kind": "paragraph",
        "text": "Stonebridge disputes $8,735.50 in snow-removal costs allocated to the common area utility pool. The landlord applied a 100% allocation of snow-removal vendor invoices to the CAM pool, but the lease's allocation methodology (Section 9.1) requires apportionment based on the ratio of leasable square footage of the building to the total leasable square footage of the entire property. Stonebridge occupies 85,000 sq ft of the 110,000 sq ft total leasable area; therefore, only 77.27% of snow-removal costs should be allocated to Stonebridge's CAM."
      },
      {
        "kind": "heading",
        "level": 3,
        "text": "Calculation"
      },
      {
        "kind": "table",
        "columns": ["Description", "Amount / Rate", "Basis"],
        "rows": [
          ["Total snow-removal vendor invoices", "$11,300.00", "Vendor invoices Dec–Mar, provided by landlord"],
          ["Stonebridge leasable square footage", "85,000 sq ft", "Lease, Section 1.4"],
          ["Total property leasable square footage", "110,000 sq ft", "Landlord's rent roll"],
          ["Allocation percentage", "77.2727%", "85,000 ÷ 110,000"],
          ["Correct CAM allocation to Stonebridge", "$8,731.82", "$11,300.00 × 77.2727%"],
          ["Landlord's applied allocation (100%)", "$11,300.00", "Landlord's CAM schedule, line 22"],
          ["Disputed over-allocation", "$8,735.50", "Original disputed amount per prior correspondence"],
          ["Corrected over-allocation", "$8,568.18", "$11,300.00 − $8,731.82"]
        ]
      },
      {
        "kind": "paragraph",
        "text": "The original disputed amount of $8,735.50 was based on a prior preliminary invoice total of $11,298.00. With the final vendor invoices totaling $11,300.00, the exact over-allocation is $8,568.18 ($11,300.00 × (100% − 77.2727%)). We are submitting the corrected figure of $8,568.18 as the precise dollar amount for this line item."
      },
      {
        "kind": "heading",
        "level": 2,
        "text": "Summary of Adjustments"
      },
      {
        "kind": "table",
        "columns": ["Disputed Line Item", "Original CAM Charge", "Corrected Amount", "Adjustment"],
        "rows": [
          ["Property tax duplicate", "$12,480.00", "$0.00", "($12,480.00)"],
          ["Snow removal over-allocation", "$11,300.00", "$8,731.82", "($2,568.18)"],
          ["Total", "$23,780.00", "$8,731.82", "($15,048.18)"]
        ]
      },
      {
        "kind": "paragraph",
        "text": "Supporting documentation (lease excerpts, landlord's CAM schedule, vendor invoices) is attached in the workpaper file. Please direct any questions to Lucia before the end of day Friday."
      }
    ]
  }
}
